[[module CSS]]

body {

    font-size: 1.1rem; 

}



h1 {

    font-family: monospace;

    text-align: center;

    font-size: 2rem;

}



.mono {

    font-family: monospace;

}



/* Container Styles */

.project-container {

    background: #fff;

    border: none;

    width: 95%;

    padding: 0.3125em 0.9375em;

    margin: 1.25em auto;

    /* Restored to original heavy shadow */

    box-shadow: 2px 2px 3px #5e5e5e82; 

    color: #000;

    display: block;

}



.red { border-left: 0.3125em solid #8a2121; }

.yellow { border-left: 0.3125em solid #dab600; }

.green { border-left: 0.3125em solid #2e5200; }



.project-inner {

    background: #fff;

    width: 90%;

    padding: 1em 1.5em;

    margin: 0.75em auto;

    text-align: left;

    /* Restored to original heavy shadow */

    box-shadow: 1px 1px 4px #5e5e5e82; 

    color: #000;

}



.inner-red { background: #fffafa; }

.inner-yellow { background: #fffffa; }

.inner-green { background: #fafffa; }



/* Credits: Components from SCP-9001 */

.overwatch-order {

  --logo-size: 4rem;

  border: medium solid firebrick;

  background: white;

  color: #444;

  display: grid;

  grid-template-columns: var(--logo-size) 1fr;

  min-height: var(--logo-size);

  border-radius: calc(var(--logo-size) / 2);

  overflow: hidden;

  margin-block: 0.5em;

}



.overwatch-order__content {

  padding-inline: 1em;

  align-content: center;

  background-image: linear-gradient(to right, #f001, #f000);

}



.overwatch-order__content p { margin-block: 0.25rem; }



.overwatch-order__title {

  font-weight: bold;

  font-size: 1.2em;

  line-height: 1.2;

}



.overwatch-order__logo {

  background-color: firebrick;

}



.overwatch-order__logo img { filter: invert(1); }



/* Forum and Memo Post Structure */

.forum {

    display: block;

    width: 100%;

    margin: 1.25em auto;

    padding-bottom: 1rem;

}



.forum__post {

    border: thin solid #bbb;

    box-shadow: 1px 1px 2px rgba(0, 0, 0, 0.08); 

    position: relative;

    background-color: #fff;

    color: #000;

    margin-top: 0.75em;

    margin-bottom: 0.75em;

    box-sizing: border-box;

}



.forum__post--op {

    width: 95%;

    margin-left: auto;

    margin-right: auto;

}



.forum__post--reply {

    width: auto;

    margin-right: 2.5%;

}



.forum__post--indent-1 {

    margin-left: calc(2.5% + 1.5rem);

}



.forum__post--indent-2 {

    margin-left: calc(2.5% + 3rem);

}



.forum__post-header {

    border-bottom: thin solid #888;

    padding: 1.1em 1.5em 1.1em 4rem;

    position: relative;

    color: #000;

    font-weight: normal;

    font-style: italic;

    width: 100%;

    box-sizing: border-box;

    background-color: #fff;

}



/* Memo Override */

.forum__post-header.memo {

    padding: 0.4em 1.5em; 

    font-style: normal;

    font-size: 1.1rem;

    border-bottom: thin solid #aaa;

}



.green .forum__post-header {

    background-color: #fafffa;

}



.forum__post-pfp {

    font-size: 1.1rem;

    font-weight: 500;

    text-align: center;

    color: var(--text, black);

    background-color: var(--bg, #eee);

    border: thin solid rgba(0, 0, 0, 0.05);

    border-radius: 99rem;

    aspect-ratio: 1 / 1;

    width: 2.2rem;

    line-height: 2.2rem;

    position: absolute;

    left: 1rem;

    top: 50%;

    transform: translateY(-50%);

    font-style: normal;

}



.forum__post-content {

    padding: 1.2em 1.5em;

    background-color: #fff;

}



/* Pseudo-elements creating branching lines for nested replies */

.forum__post--reply::before {

    content: "";

    position: absolute;

    left: -1rem;

    top: -0.75em;

    height: calc(2.15rem + 0.75em);

    border-left: thin solid #888;

}



.forum__post--reply::after {

    content: "";

    position: absolute;

    left: -1rem;

    top: 2.15rem;

    width: 1rem;

    border-bottom: thin solid #888;

}

