[[module CSS]]

/* Rate */

div.page-rate-widget-box{

    background-color: rgba(0,0,0,0);

}



/* Special Text */

:is(span.specialtext, span.st) {

    text-transform: uppercase;

    text-decoration: underline 2px;

    text-underline-offset: 3px;

    color: #8F00F8;

}



/* Hide Footnote Footer */

.footnotes-footer {

display:none;

}



/* Footnote Color */

:root {

    --fnColor: #ACCCDD;

}

/* Footnote Root */

:root {

    --posX: calc(50% - 358px - 12rem);

    --fnTransition: 0.3s;

    --fnLinger: 0.15s;

    --fnInteract: calc(var(--fnTransition) + var(--fnLinger));

}



/*--- Footnote Auto-counters --*/

#main-content {

    counter-reset: megacount1 megacount2 megacount3;

}



/* Footnotes 1 */



/*--- Footnote Superscript Number --*/

.fnnum1 {

    display: inline-block;

    width: max-content;

    text-indent: -0.475ex;

    vertical-align: super;

    line-height: 80%;

    word-break: initial;

    text-decoration: none;

    font-weight: bold;

    font-style: initial;

    color: transparent;

    position: relative;

    font-size: 80%;

    padding: .15em .05em;

    margin-right: -0.25em;

    counter-increment: megacount1;

    -webkit-user-select: none;

    user-select: none;

}

.fnnum1::after {

    content: "" counter(megacount1);

    color: var(--fnColor, #E6283C);

}

.fnnum1:hover {

    text-decoration: none;

    cursor: pointer;

    background-color: var(--fnColor, #E6283C);

}

.fnnum1:hover::after { color: white; }



/*--- Footnote Content Wrapper --*/

.fncon1 {

    position: absolute;

    right: calc(var(--posX) + 80px);

    line-height: 1.25;

    padding: 0.8125rem;

    width: 12.5rem;

    box-sizing: border-box;

    background: rgb(var(--basalt-secondary-color));

    border: .125rem solid black;

    font-size: .9125rem;

    font-weight: initial;

    font-style: normal;

    text-align: initial;

    visibility: hidden;

    opacity: 0;

    z-index: 9;

    transition:

        opacity 0.15s linear var(--fnLinger),

        right var(--fnTransition) cubic-bezier(.08,.72,.5,.94) var(--fnLinger),

        visibility 0.01s linear var(--fnInteract);

}

.fnnum1:hover + .fncon1, .fncon1:is(:hover,:focus-within) {

    opacity: 1;

    z-index: 10;

    right: var(--posX);

    visibility: visible;

    transition:

        opacity 0.15s linear,

        right var(--fnTransition) cubic-bezier(.08,.72,.5,.94);

}



.fncon1::before {

    position: absolute;

    top: 0; left: 0;

    transform: translateX(-52%) translateY(-55%) scale(1.15);

    background-color: var(--fnColor, #E6283C);

    color: white;

    content: counter(megacount1);

    font-size: initial;

    font-weight: bold;

    font-style: initial;

    padding: 0.18rem 0.32em 0.08rem;

}



/*--- Mobile Query --*/

@media only screen and (max-width: 1279px) {

    .fncon1 {

        position: fixed;

        bottom: 1.5rem;

        left: calc(15% - 50px);

        width: 70%;

        transition:

            opacity 0.15s linear var(--fnLinger),

            left var(--fnTransition) cubic-bezier(.08,.72,.5,.94) var(--fnLinger),

            visibility 0.01s linear var(--fnInteract);

    }

    .fnnum1:hover + .fncon1, .fncon1:is(:hover,:focus-within) {

        left: 15%;

        transition:

            opacity 0.15s linear,

            left var(--fnTransition) cubic-bezier(.08,.72,.5,.94);

    }

}



